use genex::prelude::*;

/// A 2k scan as cc0__fetch delivers it, at its real size: no stretch, no visible repeat.
fn scan(maps: &str, metres: f32) -> Material {
    Material::color(Color::WHITE)
        .with_base_texture(&format!("{maps}_diff_2k.jpg"))
        .with_normal_texture(&format!("{maps}_nor_gl_2k.jpg"), 1.0)
        .with_metal_rough_texture(&format!("{maps}_arm_2k.jpg"))
        .with_world_uv(metres)
        .with_stochastic_tiling(true)
        .with_macro_variation(0.12, 3.0)
}

// on_reset: each piece once.
let wall = gfx.assets().model("kit/wall.glb");
let wall_paint = gfx.assets().model("kit/wall-paint.glb");
let lockers = gfx.assets().model("kit/hero/lockers.glb");

// on_draw: a module turned to face its room, in each role's material; a hero in its own.
let place = Transform::from_translation(at).with_rotation(Quat::from_rotation_y(yaw));
frame.model_with(&wall, place, &scan("cc0/<job>/preconcrete_wall_001", 4.0));
frame.model_with(&wall_paint, place, &scan("cc0/<job>/blue_plaster_weathered", 2.0));
frame.model(&lockers, place);
frame.decal(&Decal::on_wall(centre, facing, 0.6, 1.07).with_base_texture("kit/decals/poster_space.png"));
